{
 "command": "git ls-files && cat README* 2>/dev/null | head -50",
 "description": "List repo files and README"
}

{
 "command": "cat .engramdb/memories/invoice-retention-period_01a106bc-a357-7820-be43-0abe12808f8e.md .engramdb/memories/use-structlog-not-stdlib-logging_01a106bb-496b-7f82-8183-5c98f4636529.md .engramdb/memories/money-moving-operations-emit-an-audit-event_01a106bb-bb5d-7c22-ba48-8253ac61f4ec.md; cat migrations/0001_create_invoices.sql migrations/0005_create_refunds.sql migrations/0007_add_customers.sql; cat scripts/backfill_tax.py; cat docs/ops/backfills.md; grep -rn -i \"retention\\|purge\\|3650\\|2555\" --include=*.py --include=*.md --include=*.toml . | grep -v .engramdb",
 "description": "Read retention memories, schema, and a similar script"
}

{
 "command": "head -50 migrations/000[234]*.sql migrations/0006*; cat src/billing/refunds.py src/billing/invoices.py tests/test_db.py scripts/export.py pyproject.toml; grep -rn \"psycopg\\|connect(\" --include=*.py . | head",
 "description": "Read schema, billing modules, DB usage"
}

{
 "command": "python -c \"import ast,sys;ast.parse(open('scripts/purge_invoices.py').read())\" && python -c \"\nimport sys; sys.path.insert(0,'scripts')\nfrom purge_invoices import retention_cutoff; from datetime import datetime,timezone\nprint(retention_cutoff(datetime(2026,10,4,tzinfo=timezone.utc)))\" ; python scripts/purge_invoices.py; echo exit=$?",
 "description": "Syntax check and smoke-test the script"
}

{
 "type": "hazard",
 "summary": "Refunds have no status column, so 'open refund' can't be detected; purge skips any refunded invoice",
 "content": "The retention rule says never purge an invoice with an open refund, but the `refunds` table (migrations/0005) only has id, invoice_id and refunded_cents. There is no status column, so an open refund looks the same as a settled one. scripts/purge_invoices.py therefore keeps every invoice that has any refund. Also, `invoices.finalized_at` is documented in docs/ops/backfills.md (naive UTC), but no migration in migrations/ creates it.",
 "physical": [
  "scripts/purge_invoices.py",
  "migrations/"
 ],
 "logical": [
  "compliance.retention"
 ],
 "tags": [
  "retention",
  "refunds",
  "schema"
 ],
 "invalidated_by": [
  "migrations/*refund*"
 ]
}
